using System.Globalization; using System.IO.Compression; using System.Text.Json; using GSPTaskMiningAnalyzer.Models;
namespace GSPTaskMiningAnalyzer;
public sealed class LogReader { public (List<LogEvent> Events,List<string> Errors) Read(string input){ var ev=new List<LogEvent>(); var er=new List<string>(); var rows=0; var bad=0; if(File.Exists(input)){ReadFile(input,ev,er,ref rows,ref bad);} else if(Directory.Exists(input)){var files=Directory.EnumerateFiles(input,"*.*",SearchOption.AllDirectories).Where(f=>f.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)).ToList(); var hasJsonl=files.Any(f=>f.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase)||f.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)); foreach(var f in files.Where(f=>hasJsonl?!f.EndsWith(".csv",StringComparison.OrdinalIgnoreCase):true)) ReadFile(f,ev,er,ref rows,ref bad);} else er.Add($"Input not found: {input}"); var unique=Dedup(ev); foreach(var e in unique){e.ReadRows=rows;e.BadRows=bad;e.DuplicatesRemoved=ev.Count-unique.Count;} return (unique.OrderBy(e=>e.TimestampUtc).ToList(),er);} public static List<LogEvent> Dedup(IEnumerable<LogEvent> src)=>src.GroupBy(e=>$"{e.MachineName}\u001f{e.UserName}\u001f{e.TimestampUtc:O}\u001f{e.EventType}\u001f{e.ProcessName}\u001f{e.ProcessId}\u001f{e.WindowTitle}\u001f{e.DurationSeconds?.ToString(CultureInfo.InvariantCulture)??"null"}\u001f{e.ScreenshotFile}").Select(g=>g.First()).ToList(); void ReadFile(string f,List<LogEvent> ev,List<string> er,ref int rows,ref int bad){try{ if(f.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)){ using var z=ZipFile.OpenRead(f); var hasJson=z.Entries.Any(x=>x.FullName.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase)); foreach(var e in z.Entries.Where(x=>x.FullName.EndsWith(".jsonl",StringComparison.OrdinalIgnoreCase)||(!hasJson&&x.FullName.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)))){ using var r=new StreamReader(e.Open()); ReadLines(e.FullName,r.ReadToEnd().Split('\n'),ev,er,ref rows,ref bad); }} else ReadLines(f,File.ReadLines(f),ev,er,ref rows,ref bad);}catch(Exception ex){er.Add($"{f}: {ex.Message}");}} void ReadLines(string source,IEnumerable<string> lines,List<LogEvent> ev,List<string> er,ref int rows,ref int bad){var arr=lines.Where(l=>!string.IsNullOrWhiteSpace(l)).ToArray(); if(source.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)) ReadCsv(source,arr,ev,er,ref rows,ref bad); else foreach(var l in arr){rows++; try{ev.Add(ParseJson(l,source));}catch(Exception ex){bad++; er.Add($"{source}: bad JSONL row: {ex.Message}");}}} LogEvent ParseJson(string line,string source){using var d=JsonDocument.Parse(line); var r=d.RootElement; string S(string n)=>r.TryGetProperty(n,out var v)?v.GetString()??"":""; double? D(string n){ if(!r.TryGetProperty(n,out var v)||v.ValueKind==JsonValueKind.Null||v.ValueKind==JsonValueKind.Undefined)return null; if(v.ValueKind==JsonValueKind.Number&&v.TryGetDouble(out var x))return x; throw new FormatException($"{n} must be a number or null");} int I(string n)=>r.TryGetProperty(n,out var v)&&v.TryGetInt32(out var x)?x:0; bool B(string n)=>r.TryGetProperty(n,out var v)&&v.ValueKind==JsonValueKind.True; var ts=DateTimeOffset.Parse(S("timestampUtc"),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal); return new(S("eventType") is {Length:>0} et?et:"activity",ts, DateTimeOffset.TryParse(S("timestampLocal"),out var tl)?tl:ts.ToLocalTime(),S("machineName"),S("userName"),S("processName"),I("processId"),S("windowTitle"),S("browserDomain"),B("isIdle"),D("durationSeconds"),S("screenshotFile"),S("screenshotReason"),source);} void ReadCsv(string source,string[] lines,List<LogEvent> ev,List<string> er,ref int rows,ref int bad){var h=Split(lines[0]); for(int i=1;i<lines.Length;i++){rows++; try{var c=Split(lines[i]); string V(string n){var ix=Array.IndexOf(h,n); return ix>=0&&ix<c.Length?c[ix]:"";} var ts=DateTimeOffset.Parse(V("timestampUtc"),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal); double? ds=null; var dsText=V("durationSeconds"); if(!string.IsNullOrWhiteSpace(dsText)){ if(double.TryParse(dsText,NumberStyles.Any,CultureInfo.InvariantCulture,out var x)) ds=x; else throw new FormatException("durationSeconds must be a number");} ev.Add(new(string.IsNullOrEmpty(V("eventType"))?"activity":V("eventType"),ts,DateTimeOffset.TryParse(V("timestampLocal"),out var tl)?tl:ts.ToLocalTime(),V("machineName"),V("userName"),V("processName"),int.TryParse(V("processId"),out var pid)?pid:0,V("windowTitle"),V("browserDomain"),V("isIdle").Equals("true",StringComparison.OrdinalIgnoreCase),ds,V("screenshotFile"),V("screenshotReason"),source));}catch(Exception ex){bad++; er.Add($"{source}: bad CSV row {i+1}: {ex.Message}");}}} static string[] Split(string l){var res=new List<string>();var cur="";bool q=false;for(int i=0;i<l.Length;i++){var ch=l[i]; if(ch=='\"'){ if(q&&i+1<l.Length&&l[i+1]=='\"'){cur+='\"';i++;} else q=!q;} else if(ch==','&&!q){res.Add(cur);cur="";} else cur+=ch;} res.Add(cur);return res.ToArray();}}
